<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Monsoon Market — a three.js tactical FPS</title>
<style>
  /* Monsoon Market look: night rain, neon pink and cyan, wet stone. */
  :root {
    --canvas: #0b0e1e;
    --surface: #141828;
    --hairline: #2a3050;
    --ink: #f2ede4;
    --muted: #9aa0b4;
    --pink: #ff2e88;
    --cyan: #22d3ee;
    --amber: #ffb020;
    --danger: #ff4d4d;
    --ok: #3ddc84;
    --radius: 4px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: var(--canvas); color: var(--ink); font-family: var(--font-ui); }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #flash { position: fixed; inset: 0; background: #fff; opacity: 0; pointer-events: none; transition: opacity 90ms linear; }
  #flash.on { opacity: 0.85; }
  #flash.on2 { opacity: 0.4; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%, -50%); --gap: 6px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: 0.9; }
  #crosshair i:nth-child(1) { left: 14px; top: calc(15px - var(--gap) - 7px); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 14px; top: calc(15px + var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 14px; left: calc(15px - var(--gap) - 7px); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 14px; left: calc(15px + var(--gap)); height: 2px; width: 7px; }
  #crosshair i:nth-child(5) { left: 14px; top: 14px; width: 2px; height: 2px; background: var(--pink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--ink); }
  #hitmarker.kill i { background: var(--pink); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  .panel { background: rgba(11, 14, 30, 0.82); border: 1px solid var(--hairline); border-radius: var(--radius); }

  #minimap { position: fixed; left: 16px; top: 16px; width: 200px; height: 170px; border: 1px solid var(--hairline); border-radius: var(--radius); background: rgba(11, 14, 30, 0.85); }

  #topbar { position: fixed; left: 50%; top: 14px; transform: translateX(-50%); display: flex; align-items: center; gap: 14px; padding: 8px 16px; font-family: var(--font-readout); }
  #topbar .team { font-weight: 700; font-size: 15px; }
  #team-a { color: var(--pink); }
  #team-b { color: var(--cyan); }
  #timer { font-size: 22px; font-weight: 700; }
  #round-label { font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
  #plan-label { font-size: 11px; color: var(--amber); letter-spacing: 0.06em; }

  #feed { position: fixed; right: 16px; top: 16px; display: grid; gap: 4px; justify-items: end; font-size: 12px; }
  .feed-line { padding: 3px 8px; background: rgba(11, 14, 30, 0.8); border-radius: 3px; color: var(--muted); transition: opacity 1s; }
  .feed-line.good { color: var(--ok); }
  .feed-line.bad { color: var(--danger); }
  .feed-line.fade { opacity: 0.25; }

  #radio { position: fixed; left: 16px; top: 200px; display: grid; gap: 4px; font-size: 12px; max-width: 340px; }
  .radio-line { padding: 4px 8px; background: rgba(11, 14, 30, 0.75); border-left: 2px solid var(--cyan); border-radius: 3px; color: var(--ink); transition: opacity 1s; }
  .radio-line.mine { border-left-color: var(--pink); }
  .radio-line b { color: var(--cyan); margin-right: 6px; }
  .radio-line.mine b { color: var(--pink); }
  .radio-line.fade { opacity: 0.25; }

  #vitals { position: fixed; left: 16px; bottom: 16px; display: flex; gap: 8px; font-family: var(--font-readout); }
  .vital { padding: 8px 12px; text-align: left; }
  .vital label { display: block; font-size: 9px; letter-spacing: 0.12em; color: var(--muted); }
  .vital b { font-size: 22px; font-weight: 700; }
  .vital.low b { color: var(--danger); }
  #money-value { color: var(--amber); }

  #weaponbox { position: fixed; right: 16px; bottom: 16px; padding: 10px 14px; text-align: right; font-family: var(--font-readout); }
  #weapon-name { font-size: 13px; letter-spacing: 0.06em; color: var(--ink); }
  #ammo { font-size: 34px; font-weight: 700; line-height: 1.1; }
  #ammo-reserve { font-size: 14px; color: var(--muted); }
  #slots, #util { font-size: 11px; color: var(--muted); margin-top: 2px; }
  #slots span { padding: 1px 5px; border-radius: 2px; }
  #slots span.on { background: var(--pink); color: #fff; }

  #banner { position: fixed; left: 50%; top: 84px; transform: translateX(-50%); text-align: center; padding: 12px 28px; }
  #banner-title { font-size: 26px; font-weight: 800; letter-spacing: 0.1em; color: var(--amber); }
  #banner-sub { font-size: 13px; color: var(--muted); margin-top: 2px; }

  #plant-bar { position: fixed; left: 50%; bottom: 110px; transform: translateX(-50%); width: 280px; padding: 8px 12px; text-align: center; }
  #plant-label { font-size: 11px; letter-spacing: 0.08em; color: var(--amber); margin-bottom: 6px; }
  #plant-fill { height: 6px; background: var(--amber); border-radius: 3px; width: 0%; transition: width 80ms linear; }

  #carry { position: fixed; left: 50%; bottom: 150px; transform: translateX(-50%); padding: 6px 14px; font-size: 12px; font-weight: 700; letter-spacing: 0.1em; color: #1a0d02; background: var(--amber); border-radius: var(--radius); }

  #buy { position: fixed; left: 50%; bottom: 190px; transform: translateX(-50%); width: 560px; padding: 14px 16px; }
  #buy h2 { margin: 0 0 4px; font-size: 14px; letter-spacing: 0.12em; }
  #buy h2 span { float: right; color: var(--amber); font-family: var(--font-readout); }
  #buy p { margin: 0 0 10px; font-size: 11px; color: var(--muted); }
  #buy-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
  .buy-item { pointer-events: auto; font: inherit; text-align: left; padding: 7px 8px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius); color: var(--ink); cursor: pointer; }
  .buy-item b { display: block; font-size: 11px; }
  .buy-item span { display: block; font-size: 10px; color: var(--muted); }
  .buy-item i { font-style: normal; font-size: 11px; color: var(--amber); font-family: var(--font-readout); }
  .buy-item.poor { opacity: 0.45; }

  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: rgba(11, 14, 30, 0.86); }
  .overlay[hidden] { display: none; }
  .panel-card { width: min(460px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius); }
  .panel-card h1 { margin: 0 0 8px; font-size: 30px; font-weight: 600; letter-spacing: -0.02em; }
  .panel-card h1 span { color: var(--pink); }
  .panel-card p { margin: 0 0 24px; font-size: 15px; line-height: 1.5; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 12px 18px; border: 1px solid var(--pink); border-radius: 8px; background: var(--pink); color: #fff; cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); color: var(--canvas); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: 4px; font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }
</style>
</head>
